window.ScripturaLexicons.BDAG_PART_0248 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-01\" data-source=\"BDAG\" data-search=\"νυνί advérbio temporal agora; na situação atual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νυνί</td><td>advérbio temporal</td><td>agora; na situação atual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-02\" data-source=\"BDAG\" data-search=\"νύξ, νυκτός, ἡ substantivo feminino noite; período noturno; noite figurada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νύξ, νυκτός, ἡ</td><td>substantivo feminino</td><td>noite; período noturno; noite figurada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-03\" data-source=\"BDAG\" data-search=\"νύσσω verbo picar; perfurar; cutucar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νύσσω</td><td>verbo</td><td>picar; perfurar; cutucar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-04\" data-source=\"BDAG\" data-search=\"νυστάζω verbo cochilar; ficar sonolento; estar inerte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νυστάζω</td><td>verbo</td><td>cochilar; ficar sonolento; estar inerte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-05\" data-source=\"BDAG\" data-search=\"νυχθήμερον, ου, τό substantivo neutro um dia e uma noite; vinte e quatro horas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νυχθήμερον, ου, τό</td><td>substantivo neutro</td><td>um dia e uma noite; vinte e quatro horas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-06\" data-source=\"BDAG\" data-search=\"Νῶε, ὁ nome próprio masculino indeclinável Noé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νῶε, ὁ</td><td>nome próprio masculino indeclinável</td><td>Noé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-07\" data-source=\"BDAG\" data-search=\"νωθρός, ά, όν adjetivo preguiçoso; lento; negligente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νωθρός, ά, όν</td><td>adjetivo</td><td>preguiçoso; lento; negligente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-08\" data-source=\"BDAG\" data-search=\"νῶτος, ου, ὁ substantivo masculino costas; parte posterior do corpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νῶτος, ου, ὁ</td><td>substantivo masculino</td><td>costas; parte posterior do corpo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-09\" data-source=\"BDAG\" data-search=\"ξαίνω verbo cardar; pentear lã; arranhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξαίνω</td><td>verbo</td><td>cardar; pentear lã; arranhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-10\" data-source=\"BDAG\" data-search=\"Ξανθικός, ου, ὁ substantivo masculino; mês do calendário macedônio Xântico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ξανθικός, ου, ὁ</td><td>substantivo masculino; mês do calendário macedônio</td><td>Xântico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-11\" data-source=\"BDAG\" data-search=\"ξενία, ας, ἡ substantivo feminino hospitalidade; hospedagem; aposento para hóspede BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξενία, ας, ἡ</td><td>substantivo feminino</td><td>hospitalidade; hospedagem; aposento para hóspede</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-12\" data-source=\"BDAG\" data-search=\"ξενίζω verbo hospedar; receber como hóspede; surpreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξενίζω</td><td>verbo</td><td>hospedar; receber como hóspede; surpreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-13\" data-source=\"BDAG\" data-search=\"ξενισμός, οῦ, ὁ substantivo masculino surpresa; espanto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξενισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>surpresa; espanto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-14\" data-source=\"BDAG\" data-search=\"ξενοδοχέω verbo dar hospitalidade; hospedar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξενοδοχέω</td><td>verbo</td><td>dar hospitalidade; hospedar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-15\" data-source=\"BDAG\" data-search=\"ξένος, η, ον adjetivo e substantivo estranho; estrangeiro; hóspede; anfitrião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξένος, η, ον</td><td>adjetivo e substantivo</td><td>estranho; estrangeiro; hóspede; anfitrião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-16\" data-source=\"BDAG\" data-search=\"Ξένων, ωνος nome próprio masculino Xênon BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ξένων, ωνος</td><td>nome próprio masculino</td><td>Xênon</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-17\" data-source=\"BDAG\" data-search=\"ξέστης, ου, ὁ substantivo masculino medida de capacidade; jarro; cântaro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξέστης, ου, ὁ</td><td>substantivo masculino</td><td>medida de capacidade; jarro; cântaro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-18\" data-source=\"BDAG\" data-search=\"ξηραίνω verbo secar; ressecar; ficar paralisado; amadurecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξηραίνω</td><td>verbo</td><td>secar; ressecar; ficar paralisado; amadurecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-19\" data-source=\"BDAG\" data-search=\"ξηρός, ά, όν adjetivo seco; ressequido; atrofiado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξηρός, ά, όν</td><td>adjetivo</td><td>seco; ressequido; atrofiado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0248-20\" data-source=\"BDAG\" data-search=\"ξιφίδιον, ου, τό substantivo neutro espada curta; punhal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξιφίδιον, ου, τό</td><td>substantivo neutro</td><td>espada curta; punhal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0248-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυνί</h1><div class=\"entry-meta\"><span>advérbio temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νυνί</span>, advérbio temporal (Hdt. 7, 229 e outros; SIG 259, 11 [338/337 b.c.]; PPetr III, 42 H [8] f, 4 [III b.c.]; POxy 490, 5 [124 a.d.]; 506, 25; 908, 5; LXX [Thackeray 191]; TestJob; JosAs cód. A 12, 7; 13, 5 [p. 55, 15; 57, 12 Bat.]; Joseph.; Ar. 13, 7; Just., D. 11, 2; Tat. 28, 1), forma enfática de <span class=\"greek\">νῦν</span>, produzida acrescentando-se a ela o sufixo demonstrativo <span class=\"greek\">ι</span> (Kühner-Bl. I 620; B-D-F §64, 2; Rob. 296; 523), sem modificação de significado (Mayser 456). Exceto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:1</a> v.l.; 24:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>; 9:26; 11:16 v.l.; <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ν</span>̣<span class=\"greek\">υ</span>̣<span class=\"greek\">ν</span>̣<span class=\"greek\">ί</span>̣ AcPt Ox 849; 1 Cl 47:5; 2 Cl 2:3, ocorre somente nos escritos paulinos e, neles, sempre como <span class=\"greek\">ν</span>. <span class=\"greek\">δέ</span> (a tradição manuscrita frequentemente oscila entre <span class=\"greek\">νῦν</span> e <span class=\"greek\">νυνί</span>).</p><p class=\"entry-text\">① Marcador temporal com ênfase no momento em si, agora.</p><p class=\"entry-text\">ⓐ Com o presente (Job 30:9; Jos., Ant. 14, 404) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:23</a>, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:22</a>; Phlm 9; cf. 11; talvez também AcPt Ox 849.</p><p class=\"entry-text\">ⓑ Com o perfeito em sentido de presente: <span class=\"greek\">ν</span>. <span class=\"greek\">δὲ</span> … <span class=\"greek\">πεφανέρωται</span>, mas agora … foi revelado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:21</a>.</p><p class=\"entry-text\">ⓒ Com o aoristo (Job 30:1; Just., D. 11, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:22</a>; 7:6; 11:30 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:22</a>; 2 Cl 2:3. Imperativo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:8</a>; 1 Cl 47:5.</p><p class=\"entry-text\">ⓓ Com substantivo (PRyl 111, 4 [161 a.d.] <span class=\"greek\">τὴν</span> <span class=\"greek\">νυνεὶ</span> <span class=\"greek\">γυναῖκά</span> <span class=\"greek\">μου</span>): <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀπολογία</span>, a defesa que agora apresento perante vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:1</a>.</p><p class=\"entry-text\">② Marcador temporal que enfatiza uma situação vigente, com a ideia temporal enfraquecida ou completamente ausente, agora, dadas as circunstâncias.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">ν</span>. <span class=\"greek\">δέ</span>, mas agora, como as coisas estão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:13</a>; 14:6 v.l. (Tat. 28, 1).</p><p class=\"entry-text\">ⓑ Introduzindo a situação real após uma oração ou período condicional irreal, mas, de fato <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:11</a> v.l.; 12:18; 15:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>; 9:26; 11:16 v.l.—DELG s.v. <span class=\"greek\">νυ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύξ, νυκτός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νύξ</span>, <span class=\"greek\">νυκτός</span>, <span class=\"greek\">ἡ</span> («noite», Hom. e posteriores); acerca do acusativo <span class=\"greek\">νύκταν</span> (JosAs 10:17; ApcEsdr 5:4 p. 29, 28 Tdf.), ver B-D-F §46, 1.</p><p class=\"entry-text\">① Período entre o pôr e o nascer do sol, noite.</p><p class=\"entry-text\">ⓐ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:25</a> <span class=\"greek\">φυλακὴ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νυκτός</span> (como Jos., Bell. 5, 510); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:30</a> (para a oração breve, cf. <span class=\"greek\">εἰμί</span> 5.—Sobre a cena, cf. 1 Km 28:25; Musaeus, Hero and Leander [V a.d.], verso 309 [ALudwich 1929] <span class=\"greek\">νὺξ</span> <span class=\"greek\">ἦν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:33</a>; 23:23; 27:27a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:25</a>; 22:5; 1 Cl 27:7 (Ps 18:3); GPt 5:18; AcPl Ha 5, 21. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁράματι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ν</span>., numa visão noturna Hv 3, 10, 6. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ν</span>., à meia-noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:25</a> D; 27:27b; <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὁμοίως</span>, e igualmente a noite, assim como o dia (isto é, <span class=\"greek\">μὴ</span> <span class=\"greek\">φάνῃ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίτον</span> <span class=\"greek\">αὐτῆς</span> = deveria perder um terço da luz da lua e das estrelas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:12</a> (cf. Job 3:9). Com <span class=\"greek\">ἡμέρα</span> (como En 104:8; ApcEsdr 2:9 p. 25, 30 Tdf.; ApcSed 8:2; Philo, Aet. M. 19; Ath. 24, 2; Hippol., Ref. 4, 44, 1; cf. Did., Gen. 37:13), também 1 Cl 20:2; 24:3. <span class=\"greek\">κοιμᾶται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>., <span class=\"greek\">ν</span>. <span class=\"greek\">ἐπέρχεται</span>, a noite dorme, sobrevém, versículo 3b. <span class=\"greek\">κατέλαβεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">νύξ</span>, a noite o alcançou GJs 14:1 (cf. GrBar 9:1).</p><p class=\"entry-text\">ⓑ Genitivo <span class=\"greek\">νυκτός</span>, à noite, durante a noite (Hom. e posteriores; Diod S 18, 34, 6; SIG 521, 5 [III b.c.]; PHib 36, 5 [229 b.c.]; PAmh 134, 6; 1 Macc 4:1, 5; 5:29; 2 Macc 12:9; 3 Macc 5:19; JosAs 24:3; Jos., Ant. 6, 215.—B-D-F §186, 2; Rob. 495) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:14</a>; 28:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:2</a>; 19:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:7</a>ab; AcPl Ha 5, 29; <span class=\"greek\">τῆς</span> <span class=\"greek\">ν</span>., nesta noite (X., An. 5, 7, 14; Alexis Com. 148 Kock.—B-D-F §186, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:8</a>. <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρας</span>, noite e dia (X., Symp. 4, 48, Apol. 31; BGU 246, 12; PGiss 19, 7; Jdth 11:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; 3:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:3</a>; 19:10; IRo 5:1; D 4:1; GPt 7:27; Ox 840, 34; AcPl Ha 2, 10; 3, 1. <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. (Dt 28:66; Josh 1:8; 2 Ch 6:20; 2 Esdr 14:3; Ps 1:2; Is 60:11 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:8</a>; 7:15; 12:10; 14:11; 20:10. <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. (IMagnMai 163, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:24</a>; 1 Cl 2:4. <span class=\"greek\">διὰ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρας</span>, continuamente, noite e dia (cf. UPZ 110, 87 [164 b.c.]; PTebt 48, 10 [113 b.c.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:5</a>.—Com preposição: <span class=\"greek\">διὰ</span> <span class=\"greek\">νυκτός</span>, através da noite (X., An. 4, 6, 22; Athen. 7, 276c; PGM 4, 2052) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:31</a>; <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλης</span> <span class=\"greek\">ν</span>., durante a noite inteira (cf. Just., D. 1, 4 <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλης</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a> v.l. (ver <span class=\"greek\">διά</span> A 2a). <span class=\"greek\">διὰ</span> <span class=\"greek\">νυκτός</span>, à noite, durante a noite (ver <span class=\"greek\">διά</span> A 2b e cf. ainda IGR IV, 860, 10 <span class=\"greek\">στρατηγήσαντα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">νυκτός</span>; BGU 597, 20; PTebt 332, 9; Sb 4317, 4; PGM 6, 47; 7, 407) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:19</a>; 17:10. <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ν</span>. (como Achilles Tat. 8, 19, 1) 16:9 (ver B-D-F §255, 3; Rob. 791). <span class=\"greek\">μέσης</span> <span class=\"greek\">ν</span>., à meia-noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:6</a> (ver <span class=\"greek\">μέσος</span> 1a).</p><p class=\"entry-text\">ⓒ Dativo, respondendo à pergunta «quando?» (B-D-F §200, 1; Rob. 522): <span class=\"greek\">νυκτί</span>, à noite (Hom. e outros; Philo, Aet. M. 88): <span class=\"greek\">φαίνειν</span> Dg 7:2. Plural (Phlegon: 257 Fgm. 36, 2, 1 Jac. <span class=\"greek\">τρισὶ</span> <span class=\"greek\">νυξί</span>): <span class=\"greek\">ταῖς</span> <span class=\"greek\">νυξί</span>, à noite 2:7; <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. (cf. TestAbr A 7 p. 83, 35 [Stone p. 14]; JosAs 24:13; ApcMos 2 <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ταύτῃ</span>), nesta mesma noite, esta noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:20</a>; 17:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:23</a>; <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>., na noite do mesmo dia Hv 3, 1, 2; 3, 10, 7. <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἐκείνῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a>; <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιούσῃ</span> <span class=\"greek\">ν</span>., na noite seguinte 23:11. Cf. GPt 9:35.—Com preposição: <span class=\"greek\">ἐν</span> <span class=\"greek\">ν</span>., à noite (X. e outros; SIG 527, 40 [c. 220 b.c.]; Veröffentlichungen aus der pap-Sammlung München 6, 43; 3 Macc 5:11; PsSol 4:5, 16; TestJob 24:4; Tat. 22:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a> v.l.; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. (TestJob 3:1; GrBar 9:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:10</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ταύτῃ</span> (Jdth 11:3, 5; 13:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:31</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>., versículo 34; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκείνῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. (cf. 1 Macc 13:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:3</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ᾗ</span> <span class=\"greek\">παρεδίδοτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23</a>.</p><p class=\"entry-text\">ⓓ Acusativo, respondendo à pergunta «por quanto tempo?» (Hom. e outros; B-D-F §161, 2; Rob. 469–71): <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νύκτας</span> <span class=\"greek\">τεσσεράκοντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:2</a>; 1 Cl 53:2; B 4:7; 14:2 (Ex 24:18; 34:28); GJs 1:4. <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">νύκτας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:40</a>ab (Jon 2:1); GJs 24:3; AcPl Ox 6 recto, 3f (singular em oposição ao plural Aa I 241, 11); AcPlCor 2:30. <span class=\"greek\">τριετίαν</span> <span class=\"greek\">νύκτα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπαυσάμην</span>, por três anos, noite e dia, não cessei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:31</a>. <span class=\"greek\">νύκτα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέραν</span>, noite e dia (Hyperid. 5, 13; Aeneas Tact. 380; Palaeph. p. 57, 5; Jos., Ant. 16, 260) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:7</a>; MPol 5:1. <span class=\"greek\">τὰς</span> <span class=\"greek\">νύκτας</span>, durante as noites, à noite (Biogr. p. 428; PHal 8, 4; Tob 10:7 BA) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:37</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ν</span>., durante a noite Hs 9, 11, 6. <span class=\"greek\">ὅλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ν</span>., durante a noite inteira (Amphis Com. [IV b.c.] 20, 4 Kock; Ex 14:20f; Lev 6:2 e outros; JosAs 25:3) Hs 9, 11, 8.</p><p class=\"entry-text\">② Noite como condição, noite, extensão figurada de 1: como tempo de repouso do trabalho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:4</a> (como símbolo da morte: Kaibel 1095, 4 <span class=\"greek\">νὺξ</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">καταλύει</span>). Como tempo contrastado com a consumação escatológica: <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">προέκοψεν</span>, a noite já vai adiantada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:5</a>.—B. 992. Neugebauer/Hoesen índice. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νύσσω</span>, 1º aoristo <span class=\"greek\">ἔνυξα</span> (Hom. e outros; Sir 22:19; PsSol 16:4; Philo, Leg. ad Gai. 42; Jos., Bell. 3, 335 <span class=\"greek\">δόρατι</span>; 5, 64 <span class=\"greek\">κατὰ</span> <span class=\"greek\">πλευρὰν</span> <span class=\"greek\">ν</span>.), primariamente «picar».</p><p class=\"entry-text\">① Penetrar com instrumento pontiagudo, normalmente sem perfuração violenta ou profunda, picar, perfurar: <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, alguém com alguma coisa: <span class=\"greek\">καλάμῳ</span> <span class=\"greek\">αὐτόν</span> GPt 3:9 (cf. Diog. L. 2, 109 <span class=\"greek\">νυχθῆναι</span> <span class=\"greek\">καλάμῳ</span> [Eubúlides morreu depois de ser perfurado por junco agudo enquanto nadava]; Hesychius Miles., Viri Ill. c. 5 JFlach [1880]; SibOr 8, 296). <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, alguma coisa com alguma coisa: <span class=\"greek\">λόγχῃ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πλευράν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:34</a> (para assegurar que Jesus estava realmente morto, com modificação da ferida mais intensa sugerida por <span class=\"greek\">ἐκκεντέω</span> [q.v.] na citação de Zech 12:12, numa leitura de origem incerta; ver Field, Notes 108); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:49</a> v.l. (Plut., Cleom. 37, 16: Panteu pica Cleômenes no tornozelo com uma adaga para determinar se está morto).</p><p class=\"entry-text\">② Tocar suavemente, dar um pequeno empurrão ou cutucão para despertar alguém do sono (Od. 14, 485; Plut., Mor. 7e; Diog. L. 6, 53; 3 Macc 5:14): <span class=\"greek\">νύξας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πλευρὰν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Πέτρου</span> <span class=\"greek\">ἤγειρεν</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:7</a> D. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> … <span class=\"greek\">νύσσει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Παῦλον</span> AcPl Ha 7, 28.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυστάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νυστάζω</span>, futuro, 3ª pessoa do singular <span class=\"greek\">νυστάξει</span> LXX; 1º aoristo <span class=\"greek\">ἐνύσταξα</span> (ver B-D-F §71), estar quase adormecido, cabecear, ficar sonolento, cochilar (Aristoph., Hippocr. e outros; PCairZen 534, 35 [III b.c.]; LXX; ApcMos 38): <span class=\"greek\">ἐνύσταξαν</span> <span class=\"greek\">πᾶσαι</span>, todas ficaram sonolentas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:5</a>.—Figuradamente, estar sonolento, inerte (Pla.; Ps. 118:28 v.l.; PsSol 16:1; Philo, Congr. Erud. Gr. 81): da retribuição personificada, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀπώλεια</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ν</span>., a destruição deles não está cochilando, isto é, está a caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:3</a>.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυχθήμερον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νυχθήμερον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">νύξ</span>, <span class=\"greek\">ἡμέρα</span>; Petosiris, Fgm. 7 linha 58; Herm. Wr. em Stob. 1, 21, 9 W.=414, 2 Sc.; Galen VII 508 K.; Cleomedes Astron. [II a.d.] 1, 6, 30f; 2, 1, 73 HZiegler; Anecdota Astrologica [ALudwich, Maximi et Ammonis Carmina 1877] p. 125, 7; Cyranides p. 58, 14; Themist., Paraphr. Aristot. I p. 372, 3 Spengel; Proclus, em Tim. Platon. índice EDiehl. Cf. Mitt-Wilck II/2, 78, 6 [376/8 a.d.] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τέσσαρας</span> <span class=\"greek\">ὅλας</span> <span class=\"greek\">νυχθημέρους</span> [B-D-F §121; ver Mlt-H. 269; 283]; Kühner-Bl. II 318.—Como adjetivo já em Peripl. Eryth. c. 15), um dia e uma noite = 24 horas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:25</a>.—EKönig, Kalenderfragen: ZDMG 60, 1906, 605ff, especialmente 608–12.—DELG s.v. <span class=\"greek\">νύξ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νῶε, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νῶε</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">נֹחַ</span>), Noé (Gen 5:29 e outros; En 107:3; TestBenj 10:6; ParJer 7:8; GrBar, Philo, Just.; Mel., P. 83, 624f; em Joseph., <span class=\"greek\">Νῶχος</span>, <span class=\"greek\">ου</span> [Ant. 1, 99]); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:36</a>. Como pregador do arrependimento 1 Cl 7:6 (cf. Jos., Ant. 1, 74 [SRappaport, Agada u. Exegese bei Fl. Josephus 1930, 93f]; SibOr 1, 127ff; Jubilees 7:20–39). Semelhantemente, como <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">κῆρυξ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:5</a> (Noé como <span class=\"greek\">δίκαιος</span> Gen 6:9; Wsd 10:4; Sir 44:17; Philo, Congr. Erud. Gr. 90, Migr. Abr. 125; cf. SibOr 1, 126 <span class=\"greek\">δικαιότατος</span>). <span class=\"greek\">πιστὸς</span> <span class=\"greek\">εὑρεθείς</span> (cf. SibOr 1, 120 <span class=\"greek\">πιστότατος</span>) 1 Cl 9:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">Ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:20</a> (ESelwyn, 1 Pt ’46, 328–33); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:37</a>. <span class=\"greek\">Ν</span>. na arca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:27</a>. Com Jó e Daniel 2 Cl 6:8 (Ezk 14:14ff).—JLewis, A Study of the Interpr. of Noah and the Flood in Jewish and Christian Lit. ’68.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωθρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νωθρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hippocr. e outros; Herm. Wr. 10, 24a <span class=\"greek\">ν</span>. <span class=\"greek\">ψυχ</span> <span class=\"greek\">ή</span>; PSI XIV 1386 verso, 6 [I b.c./I a.d.]; PBrem 61, 15; LXX), preguiçoso, indolente: <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">παρειμένος</span> <span class=\"greek\">ἐργάτης</span>, trabalhador preguiçoso e descuidado 1 Cl 34:1 (cf. Sir 4:29). <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">νωθροὶ</span> <span class=\"greek\">γένησθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:12</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀκοαῖς</span>, lento para ouvir = de audição difícil (ver <span class=\"greek\">ἀκοη</span> 3 e Heliod. 5, 1, 5 <span class=\"greek\">νωθρότερος</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀκοήν</span>) 5:11.—DELG s.v. <span class=\"greek\">νωθής</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῶτος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νῶτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores [mas no ático quase sempre <span class=\"greek\">τὸ</span> <span class=\"greek\">νῶτον</span>]; também X., Equ. 3, 3; Aristot., HA 3, 3; 12, 5; LXX [Thackeray p. 155]; PsSol 10:2 [acusativo <span class=\"greek\">νῶτον</span>]; TestSol 14:1 [<span class=\"greek\">κατὰ</span> <span class=\"greek\">νώτου</span>, mas acusativo como variante de leitura]; TestIss 5:3 [<span class=\"greek\">τὸν</span> <span class=\"greek\">νῶτον</span>]; TestNapht 5:6 [<span class=\"greek\">νώτου</span>]; Philo, Aet. M. 128 [<span class=\"greek\">νῶτα</span>]; Jos., Ant. 12, 338; 424 [<span class=\"greek\">τὰ</span> <span class=\"greek\">νῶτα</span>]; Just., D. 53, 1 [<span class=\"greek\">τὸν</span> <span class=\"greek\">νῶτον</span>]; B-D-F §49, 2; Mlt-H. 124.—PTebt 21, 8 [II b.c.], acusativo <span class=\"greek\">νῶτον</span>), parte posterior do corpo, do pescoço à pelve, costas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:10</a> (Ps 68:24); 5:1 (Is 50:6).—B. 211. DELG s.v. <span class=\"greek\">νῶτον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξαίνω</span> (Hom. e outros; Aristoph., Theophr., Anth. Pal.; não ocorre na LXX; figuradamente em Jos., Ant. 1, 46, Bell. 6, 304), arranhar ou pentear, especialmente lã durante a preparação do fio, pentear, cardar; encontrado na leitura original do Códice <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">א</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>, onde foi apagado e posteriormente revelado por luz ultravioleta (TSkeat, ZNW 37, ’38, 211–14 [cf. POxy 2221 col. 2, 8 e nota]): <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ξένουσιν</span> (<span class=\"greek\">ξαίν</span>.) em lugar de <span class=\"greek\">πῶς</span> <span class=\"greek\">αὐξάνουσιν</span> dos textos. Isto talvez permita restaurar o dito Ox 655, 1 (b), 9f p. 23 (=Kl. T. 83 p. 23; ASyn. 67, 33; ver GTh 36) e ler ali <span class=\"greek\">ο</span>]<span class=\"greek\">ὐ</span> <span class=\"greek\">ξαίνει</span> em lugar de <span class=\"greek\">α</span>]<span class=\"greek\">ὐξα</span>[<span class=\"greek\">ι</span>]<span class=\"greek\">νει</span> (mas ver Fitzmyer p. 544 e Betz, SM 477). Isso poderia significar que <span class=\"greek\">ξαίνω</span> figurava na fonte comum de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:27</a>; nesse caso haveria três negações acerca dos lírios em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>, como também acerca das aves do versículo 26.—PKatz, JTS 5, 2, ’54, 207–9; TGlasson, Carding and Spinning: POxy 655: JTS 13, ’62, 331f.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ξανθικός, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; mês do calendário macedônio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ξανθικός</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (assim em Diod S 18, 56, 5, num edito de remissão emitido pelos macedônios na época dos Diádocos, <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ξανθικοῦ</span> <span class=\"greek\">μηνός</span>; 2 Macc 11:30; Joseph., índice. A forma correta é <span class=\"greek\">Ξανδικός</span>; ver OGI índice V; Mayser 180), Xântico, mês do calendário macedônio. A data do martírio de Policarpo, <span class=\"greek\">μηνὸς</span> <span class=\"greek\">Ξανθικοῦ</span> <span class=\"greek\">δευτέρᾳ</span> <span class=\"greek\">ἱσταμένου</span> MPol 21, corresponde a 22 ou 23 de fevereiro.—Lghtf., Apost. Fathers II2/1, 1889, 677ff; ESchwartz, Jüd. u. christl. Ostertafeln: AGG VIII 6, 1905, 125ff.—EBickerman, Chronology of the Ancient World 2 ’80, listas pp. 20 e 48.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξενία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξενία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ξένος</span>; Hom. e outros; inscrições, papiros, Sir 29:27 v.l.; Philo, Joseph., empréstimo no rabínico), hospitalidade, acolhimento oferecido a hóspede (assim na maioria dos casos), menos frequentemente o lugar em que o hóspede é alojado, quarto de hóspedes (Suda e, de modo semelhante, Hesychius identificam <span class=\"greek\">ξενία</span> com <span class=\"greek\">καταγώγιον</span>, <span class=\"greek\">κατάλυμα</span>. Cf. também Sb 3924, 7; 17 [19 a.d.]; PMich 473, 13 [II a.d.]; PSI 50, 16 [IV–V a.d.]; Philo, Mos. 2, 33; Jos., Ant. 1, 200; 5, 147; Ps.-Clem., Hom. 1, 15; 8, 2; 12, 24; 14, 1; 8). Nas duas passagens da nossa literatura nas quais <span class=\"greek\">ξ</span>. ocorre, ambos os sentidos são possíveis, embora o segundo talvez seja mais provável. <span class=\"greek\">ἑτοιμάζειν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ξενίαν</span>, preparar um aposento para hóspede Phlm 22 (Ps.-Clem., Hom. 12, 2 <span class=\"greek\">τὰς</span> <span class=\"greek\">ξενίας</span> <span class=\"greek\">ἑτοιμάζοντες</span>.—<span class=\"greek\">ξενία</span> = aposento para hóspedes também no escólio sobre Nicander, Ther. 486. Cf. latim hospitium parare). Acerca da hospedagem de Paulo em Roma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:23</a> (sobre a questão de <span class=\"greek\">ξ</span>. aqui = <span class=\"greek\">μίσθωμα</span> no versículo 30, ver Lghtf. acerca de Phlm 22 e no comentário de Phil p. 9; ver também HCadbury, JBL 45, 1926, 320ff; Haenchen ad loc.).—DELG s.v. <span class=\"greek\">ξένος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξενίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξενίζω</span> (<span class=\"greek\">ξένος</span>), 1º aoristo <span class=\"greek\">ἐξένισα</span>. Passivo: 1º futuro <span class=\"greek\">ξενισθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐξενίσθην</span> (Hom. e outros; inscrições, papiros, LXX; TestAbr B; Philo, Joseph., Ath.).</p><p class=\"entry-text\">① Demonstrar hospitalidade, receber como hóspede, hospedar (Hom. e outros): <span class=\"greek\">τινά</span>, alguém (X., Cyr. 8, 3, 35; Diod S 14, 31, 3; Aelian, VH 13, 26) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:23</a>. <span class=\"greek\">ἀγγέλους</span> (TestAbr B 2 p. 106, 21f [Stone p. 60]; cf. Polyaenus 6, 1, 3 <span class=\"greek\">ξ</span>. <span class=\"greek\">θεούς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:2</a> (segundo Gen 18:3; 19:2f). O objeto deve ser suprido pelo contexto (Sir 29:25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:7</a>.—Passivo: ser hospedado, permanecer alojado, <span class=\"greek\">ἐν</span> <span class=\"greek\">οἰκίᾳ</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:32</a>. <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>, na casa de alguém (Diod S 14, 30, 3; Philo, Abr. 131; Jos., Ant. 12, 171), versículo 6; 21:16 (sobre a construção, ver B-D-F §294, 5; Rob. 721); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a> v.l. <span class=\"greek\">ἐνθάδε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:18</a>.</p><p class=\"entry-text\">② Provocar forte reação psicológica mediante a introdução de algo novo ou estranho, surpreender, causar espanto (Polyb. 3, 114, 4; Diod S 12, 53, 3; Jos., Ant. 1, 45): <span class=\"greek\">ξενίζοντά</span> <span class=\"greek\">τινα</span>, coisas surpreendentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:20</a>.—Passivo: ficar surpreso, admirar-se (Polyb.; M. Ant. 8, 15; PStras 35, 6; PIand 20, 1; Ath., R. 16 p. 67, 9), com dativo da coisa que causa surpresa (Polyb. 1, 23, 5; 3, 68, 9): <span class=\"greek\">μὴ</span> <span class=\"greek\">ξενίζεσθε</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πυρώσει</span>, não vos surpreendais (nem vos perturbeis, ESelwyn, 1 Pt ’46, 212) com a provação ardente entre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:12</a>; variante <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κτλ</span>. (correspondente a Polyb. 2, 27, 4; UPZ 146, 4; 6 [II b.c.]; Jos., Ant. 1, 35). Também <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, versículo 4 (B-D-F §196; ver Rob. 532). Sem complemento 2 Cl 17:5.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξενισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξενισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ξενίζω</span>; Pla. e outros; Polyb. 15, 17, 1; Diod S 3, 33, 7; inscrições; Pr 15:17; TestAbr B 13 p. 117, 20 [Stone p. 82] «abrigo»), forte reação psicológica provocada por algo estranho, espanto: <span class=\"greek\">ξενισμὸν</span> <span class=\"greek\">παρεῖχεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καινότης</span> <span class=\"greek\">αὐτοῦ</span>, a novidade daquilo causou espanto IEph 19:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξενοδοχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξενοδοχέω</span> (<span class=\"greek\">ξένος</span>, <span class=\"greek\">δέχομαι</span>), 1º aoristo <span class=\"greek\">ἐξενοδόχησα</span> (Maximus Tyr. 26, 9a; Cass. Dio 78, 3; Ps.-Lucian, Amor. 47 p. 450; Graec. Venet. Gen 26, 17. Substitui a forma mais antiga [Eur., Hdt. e outros] <span class=\"greek\">ξενοδοκέω</span> e é rejeitado pelos aticistas; Phryn. 307 Lob.), mostrar hospitalidade, sem complemento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:10</a>.—TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξένος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξένος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (ver os quatro verbetes anteriores; Hom. e posteriores; empréstimo no rabínico).</p><p class=\"entry-text\">① Adjetivo: relativo a não ser familiar por algo ser desconhecido, estranho.</p><p class=\"entry-text\">ⓐ Com referência a algo proveniente de fonte externa, estranho, estrangeiro.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Porque provém de fonte externa: <span class=\"greek\">ξ</span>. <span class=\"greek\">δαιμόνια</span>, divindades estrangeiras (<span class=\"greek\">δαιμόνιον</span> 1 e Achilles Tat. 2, 30, 1; Jos., C. Ap. 2, 251; 267 <span class=\"greek\">ξένους</span> <span class=\"greek\">θεούς</span>; cf. Plut., Pompey 631 [24, 5], «sacrifícios estranhos») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:18</a>. <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">ξένῳ</span> AcPl Ox 6, 11 (=Aa I 241, 14). <span class=\"greek\">διδαχαί</span>, ensinamentos estranhos (provenientes de fora da comunidade; cf. Jos., Bell. 2, 414 <span class=\"greek\">θρησκεία</span> <span class=\"greek\">ξένη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a>; Hs 8, 6, 5 v.l.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Porque é algo nunca ouvido antes, extensão figurada de <span class=\"greek\">α</span>: estranho por sua espécie, surpreendente, inaudito, alheio (Aeschyl., Prom. 688; Diod S 3, 15, 6; 3, 52, 2; M. Ant. 8, 14; POxy 1772, 3 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ξένον</span>; Wsd 16:2, 16; 19:5; Philo, Mos. 1, 213; Just., A I, 16, 4, cf. D. 2, 2 <span class=\"greek\">τὸ</span> <span class=\"greek\">ξ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span>; Tat. 33, 2; Mel., P. 53, 387; <span class=\"greek\">τὸ</span> <span class=\"greek\">ξ</span>. Did., Gen. 186, 7; <span class=\"greek\">ξένον</span> <span class=\"greek\">θαῦμα</span> Hippol., Ref. 4, 46, 2) PEg2 64. <span class=\"greek\">ὡς</span> <span class=\"greek\">ξένου</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">συμβαίνοντος</span>, como se algo inaudito vos estivesse acontecendo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:12</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">ξένα</span> <span class=\"greek\">ὁμιλῶ</span>, nada tenho de estranho para dizer Dg 11:1. Com dativo de pessoa: <span class=\"greek\">ἡ</span> <span class=\"greek\">ξένη</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐκλεκτοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">στάσις</span>, a rebelião (que é) estranha aos eleitos de Deus 1 Cl 1:1.—Papias (2:11, Eus. sobre Papias) <span class=\"greek\">ξένας</span> <span class=\"greek\">τέ</span> <span class=\"greek\">τινας</span> <span class=\"greek\">παραβολὰς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωτῆρος</span>, algumas parábolas estranhas do Salvador.</p><p class=\"entry-text\">ⓑ Com referência a entidade que não conhece algo, com genitivo <span class=\"greek\">τινός</span>: estranho a alguma coisa, dela afastado, não familiarizado com ela, sem interesse por ela (Soph., Oed. R. 219; Pla., Apol. 17d; Heliod. 10, 14; POxy 1154, 8 [I a.d.] <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ξένος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐνθάδε</span>.—B-D-F §182, 3; Rob. 516): <span class=\"greek\">ξ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">διαθηκῶν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαγγελίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:12</a>.</p><p class=\"entry-text\">② Como substantivo: entidade envolvida na experiência de não familiaridade.</p><p class=\"entry-text\">ⓐ Alguém que chega como desconhecido. <span class=\"greek\">ὁ</span> <span class=\"greek\">ξένος</span>, estranho, estrangeiro (Orig., C. Cels. 5, 27, 18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:7</a>; 3J 5. Em oposição a <span class=\"greek\">πολίτης</span> (cf. Ael. Aristid. 13 p. 163 D.; SIG 495, 115; 708, 16f; 729, 4 e outros; OGI 764, 18; Philo, Poster. Cai. 109; Jos., Ant. 11, 159, Vi. 372) Dg 5:5. Com <span class=\"greek\">πάροικοι</span> (em oposição a <span class=\"greek\">συμπολίτης</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:19</a> (cf. SIG 799, 24f <span class=\"greek\">ξ</span>. <span class=\"greek\">ἢ</span> <span class=\"greek\">μέτοικος</span>). Com <span class=\"greek\">παρεπίδημοι</span> (Diod S 4, 27, 3 e OGI 268, 9 <span class=\"greek\">τ</span>. <span class=\"greek\">παρεπιδημοῦντας</span> <span class=\"greek\">ξένους</span>; cf. 339, 29; Just., A I, 67, 6 <span class=\"greek\">τοῖς</span> <span class=\"greek\">παρεπιδήμοις</span> <span class=\"greek\">οὖσι</span> <span class=\"greek\">ξένοις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a>; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπιδημοῦντες</span> <span class=\"greek\">ξ</span>., os estrangeiros que ali residiam (ou visitavam) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:21</a> (SIG 1157, 80f <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐνδημούντων</span> <span class=\"greek\">ξένων</span>).—Em razão de um código de hospitalidade profundamente enraizado no mundo mediterrâneo (para uma perspectiva semítica, ver especialmente Gen 18:1–8; o mundo grego encontra sua sanção em Homero, ver especialmente Od. 6, 198–210, com a descrição dos feácios em contraste com a falta de hospitalidade de Polifemo, Od. 9, 272–80), <span class=\"greek\">ξ</span>. frequentemente implica o estatuto de suplicante que deveria ser tratado como hóspede: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:35</a>, 38, 43f (sobre proteção divina de um completo estranho, cf. Od. 6, 207f [=14, 57f]; 9, 270f; 17, 483–87).</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ἡ</span> <span class=\"greek\">ξένη</span>, país estrangeiro (Soph., Phil. 135; POxy 251, 11; 253, 7; <span class=\"greek\">τις</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ξένης</span> Hippol., Ref. 9, 20, 1) Dg 5:5. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξένης</span> (X., Resp. Lac. 14, 4; Epict. 1, 27, 5; Plut., Mor. 576c; BGU 22, 34 [114 a.d.]; 159, 7; PFay 136, 10; ACalderini, <span class=\"greek\">ΟΙ</span> <span class=\"greek\">ΕΠΙ</span> <span class=\"greek\">ΞΕΝΗΣ</span>, JEA 40, ’54, 19–22 [numerosos papiros citados]; 2 Macc 5:9; 9:28; Philo, Leg. ad Gai. 15; Jos., Ant. 18, 344): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξένης</span> <span class=\"greek\">κατοικεῖν</span>, residir em país estrangeiro Hs 1:1, 6.</p><p class=\"entry-text\">ⓒ <span class=\"greek\">ὁ</span> <span class=\"greek\">ξένος</span>, o anfitrião, aquele que oferece hospitalidade e assim trata o estranho como hóspede (desde Il. 15, 532; também Mel., P. 51, 375 <span class=\"greek\">ξένον</span> <span class=\"greek\">ᾐδίκησεν</span>), com genitivo (X., An. 2, 4, 15): <span class=\"greek\">ὁ</span> <span class=\"greek\">ξ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span>, anfitrião meu e de toda a congregação, provavelmente porque disponibilizou espaço para suas reuniões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:23</a>.—B. 1350–52. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ξένων, ωνος</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ξένων</span>, <span class=\"greek\">ωνος</span> (desde o V b.c.; JKirchner, Prosopographia Attica II nº 11320ff; Daniele Foraboschi, Onomasticon alterum papyrologicum [Testi e documenti, serie papyrologica 2, XVI], Milão, p. 211; Preisigke, Namenbuch p. 238), Xênon, um presbítero em Corinto AcPlCor 1:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξέστης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξέστης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Diosc.; Epict. 1, 9, 33f; 2, 16, 22; OGI 521, 24; O. Wilck II, 1186, 2; Sb II, lista de palavras p. 360; Jos., Ant. 8, 57, Vi. 75. Empréstimo no rabínico.—Considerado pela maioria como corrupção do latim sextarius; Mlt-H. 155, nota 3, manifesta algumas dúvidas a esse respeito), uma medida aproximadamente equivalente a 1/2 litro (FHultsch, Griech. u. röm. Metrologie2 1882, 103ff; APF 3, 1906, 438; O. Wilck I 762f). Porém, passa então a significar simplesmente cântaro, jarro, sem referência à quantidade que contém (POxy 109, 21 <span class=\"greek\">ξέσται</span> <span class=\"greek\">χαλκοῦ</span>; 921, 23; Cat. Cod. Astr. VIII/3, 139), com <span class=\"greek\">ποτήριον</span>, <span class=\"greek\">χαλκίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:4</a>; cf. versículo 8 v.l.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξηραίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξηραίνω</span> (<span class=\"greek\">ξηρός</span>), futuro <span class=\"greek\">ξηρανῶ</span> LXX; 1º aoristo <span class=\"greek\">ἐξήρανα</span>. Passivo: futuro, 3ª pessoa do singular <span class=\"greek\">ξηρανθήσεται</span> LXX; 1º aoristo <span class=\"greek\">ἐξηράνθην</span>; perfeito <span class=\"greek\">ἐξήραμμαι</span>, particípio <span class=\"greek\">ἐξηραμμένος</span> (Hom. e outros; papiros, LXX, En, TestSol; TestLevi 4:1; ParJer 19:17; 4 Esdr 8:23 [Fgm. c]; Joseph.).</p><p class=\"entry-text\">① Interromper um fluxo (como o de seiva ou de outro líquido) em algo e assim causar secura, secar, ressecar.</p><p class=\"entry-text\">ⓐ Ativo: secar, ressecar, com <span class=\"greek\">τὶ</span>, alguma coisa (Thu. 1, 109, 4; escólio sobre Nicander, Ther. 831 <span class=\"greek\">ξηραίνει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δένδρον</span>; PGM 13, 27 <span class=\"greek\">ξήρανον</span> [isto é, <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνθη</span>]; Is 42:15; Jer 28:36; Just., D. 107, 3), acerca do sol: <span class=\"greek\">τὸν</span> <span class=\"greek\">χόρτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a>.</p><p class=\"entry-text\">ⓑ Passivo em sentido ativo, ficar seco, ressecar, murchar; de árvores (POxy 53, 10; Jo 1:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:20</a>f. De plantas sem boas raízes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:6</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:24</a> (Is 40:7). Um ramo da videira, quando cortado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:6</a>. De plantas em geral Hs 9, 21, 1; 3. Da água (Gen 8:7; 3 Km 17:7; Is 19:5f <span class=\"greek\">ποταμός</span>; En 101:7; Jos., Bell. 5, 409 <span class=\"greek\">πηγή</span>; TestLevi 4:1), acerca de um rio: secar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:12</a>. De um fluxo de sangue: <span class=\"greek\">εὐθὺς</span> <span class=\"greek\">ἐξηράνθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πηγὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span> <span class=\"greek\">αὐτῆς</span>, a hemorragia dela cessou imediatamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:29</a>.</p><p class=\"entry-text\">② Ficar seco a ponto de ficar imobilizado, ficar paralisado, passivo com sentido ativo, extensão figurada de 1. Assim como as plantas morrem por causa da seca, o corpo humano é lesado por determinadas coisas nocivas (Hippocr., <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντὸς</span> <span class=\"greek\">παθῶν</span> 22 vol. VII 222 L.—PUps 8, 4 <span class=\"greek\">καταξηρανθήτω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κλίνοις</span> = que seu corpo resseque no leito de enfermidade): <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἐξηραμμένην</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χεῖρα</span>, homem que tinha uma mão atrofiada (isto é, incapaz de movimentá-la; cf. 3 Km 13:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:1</a>, 3 v.l. Da mesma forma, todo o corpo de um rapaz possesso fica rígido: <span class=\"greek\">ξηραίνεται</span>, ele se enrijece 9:18 (Theocr. 24, 61 <span class=\"greek\">ξηρὸν</span> <span class=\"greek\">ὑπαὶ</span> <span class=\"greek\">δείους</span> = rígido de medo. Semelhantemente Psellus p. 212, 6).</p><p class=\"entry-text\">③ Ficar seco e, portanto, pronto para a colheita, estar maduro, passivo de cereais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:15</a>.—DELG s.v. <span class=\"greek\">ξηρός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξηρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξηρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hipponax [VI b.c.]; Hdt. e posteriores; inscrições, papiros, LXX, En; TestSol 10:6 C; TestZeb 2:7; JosAs 13:8; Philo; Jos., Bell. 3, 228, Ant. 5, 249; Just., D. 117, 3; 131, 3; Mel.; Hs 8, 4, 6, adjetivo com duas terminações?).</p><p class=\"entry-text\">① Relativo à perda completa de umidade, seco, ressequido, literalmente, acerca de <span class=\"greek\">ξύλον</span> (q.v. 3 e GDI 4689, 108 [Messênia] <span class=\"greek\">ξηρὰ</span> <span class=\"greek\">ξύλα</span>; PEdg 93 [=Sb 6808], 1 [256 b.c.]; Is 56:3; Ezk 17:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:31</a>; Hs 4:4. De árvores (Lucian, Sat. 9) 3:1ff; 4:1, 4. De ramos (POxy 1188, 4 [13 a.d.]; Kaibel 1039, 14) 8, 1, 6f e 11f; 8, 2, 6; 8, 4, 4ff; 8, 5, 2ff; 8, 6, 4f; 8, 8, 1 e 4; 8, 9, 1; 8, 10, 1 e 3. De plantas 9, 1, 6; 9, 21, 1; por extensão, também na imagem de <span class=\"greek\">θεμέλια</span> (correspondente a <span class=\"greek\">ῥίζαι</span>) 9, 21, 2 e até de pessoas: <span class=\"greek\">δίψυχοι</span>, ibidem; cf. 4:4. De sementes 1 Cl 24:5. <span class=\"greek\">ἡ</span> <span class=\"greek\">ξ</span>. <span class=\"greek\">γῆ</span>, terra seca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:29</a>. Também simplesmente <span class=\"greek\">ἡ</span> <span class=\"greek\">ξηρά</span>, a (terra) seca (X., Oec. 17, 2; 19, 7; Aristot., HA 5, 10; Gen 1:9 e outros na LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:29</a> v.l.; Hv 3, 2, 7; 3, 5, 3. Com <span class=\"greek\">θάλασσα</span> (Jon 1:9; Hg 2:21; 1 Macc 8:23, 32; En 97:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:15</a>.</p><p class=\"entry-text\">② Relativo a estar enrugado ou atrofiado e, portanto, imobilizado em virtude de enfermidade, ressequido, atrofiado, paralisado, extensão figurada de 1 (cf. <span class=\"greek\">ξηραίνω</span> 2; <span class=\"greek\">ξηρότης</span> Galen VII 666, 1 K. = doença debilitante.—<span class=\"greek\">ξηρός</span> neste sentido na terceira estela de Epidauro linha 108, conforme a leitura de RHerzog, D. Wunderheilungen v. Ep. 1931, 32 e 138. <span class=\"greek\">ἡμίξηρος</span> = semirrígido, Hippiatr. I 185, 9; <span class=\"greek\">χεὶρ</span> <span class=\"greek\">ἡμίξηρος</span> TestSim 2, 12. Cf. também Hipponax 10 West [30 Degani; 11 Diehl3] <span class=\"greek\">λιμῷ</span> <span class=\"greek\">γένηται</span> [Diehl aceita optativo <span class=\"greek\">γένοιτο</span> contra os códices] <span class=\"greek\">ξηρός</span>; Hos 9:14 <span class=\"greek\">μαστοὶ</span> <span class=\"greek\">ξηροί</span>; Psellus p. 27, 17 <span class=\"greek\">νηδὺς</span> <span class=\"greek\">ξηρά</span>, sobre o ventre de mulher idosa): <span class=\"greek\">χεὶρ</span> <span class=\"greek\">ξηρά</span>, mão atrofiada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:6</a>, 8 (Mel., P. 78, 562; 90, 668). <span class=\"greek\">ξηροί</span>, atrofiados, paralíticos (Lucian, Tox. 24 sobre uma mulher <span class=\"greek\">ξηρὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἥμισυ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a>.—Sobre o significado da palavra, DHesseling, Sertum Nabericum 1908, 145–54; Renehan ’75, 145f.—B. 1076. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0248-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξιφίδιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξιφίδιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ξίφος</span>; Aristoph., Thu. e outros; POxy 936, 9 [III a.d.]; Jos., Ant. 20, 164, Vi. 293), espada curta, punhal MPol 16:1.</p></section></article>\n"};
